//! Frozen shared-memory replay for measured and generated bytes; see CONNECTED.md.

use super::super::connected_anchor::{self, Trace};
use super::super::connected_context::{self, Context};
use super::super::connected_decode::{self, Options};
use super::super::connected_route::Draw;
use super::super::connected_signal::{Kind, Record};
use super::super::connected_state::State;
use super::super::connected_store::Store;
use super::super::core_corpus::END;
use super::super::generation::recent_window;
use super::super::shared::Prefix;
use super::Budget;
use anyhow::Result;
use serde_json::{json, Value};

pub(super) struct Replay<'a> {
    state: State,
    store: &'a mut Store,
    /// Whether route entries take the shared-section read (false: `heldout_without_shared`).
    read: bool,
    /// This replay's own contextual-row buffer (CONNECTED.md §Contextual rows).
    context: Option<Context>,
    /// Whether `warm` fills the buffer; false only in the wiring test.
    warm: bool,
}

impl<'a> Replay<'a> {
    pub fn new(state: &State, store: &'a mut Store) -> Result<Self> {
        Self::with_read(state, store, true)
    }

    /// A frozen replay whose route entries skip the shared read when `read` is false.
    pub fn with_read(state: &State, store: &'a mut Store, read: bool) -> Result<Self> {
        // Slicing and visit normalization follow the checkpointed options, not ambient knobs.
        super::super::tuning::set_connected(&state.options);
        let mut scratch = State::restore(&state.payloads()?, state.geometry, state.seed)?;
        scratch.attach_view(store.view)?;
        // Same eviction policy as training (CONNECTED.md §Visit balance).
        scratch.memory = super::super::connected_balance::memory(state.geometry, &state.options)?;
        scratch.epoch = 0;
        Ok(Self {
            context: connected_context::fresh(state.geometry, &state.options),
            state: scratch,
            store,
            read,
            warm: true,
        })
    }

    /// Test switch: observe only from `start` (no contextual-row warm-up).
    #[cfg(test)]
    pub fn without_warm_up(mut self) -> Self {
        self.warm = false;
        self
    }

    /// First position to observe for a first observed position `start` whose prefix has `length`
    /// bytes: a full window earlier under contextual rows (the warm-up), else `start`.
    pub fn observed_from(&self, start: usize, length: usize) -> usize {
        if self.context.is_some() && self.warm {
            connected_context::warm_start(start as u64, length) as usize
        } else {
            start
        }
    }

    /// Scores `target` after `bytes`, whose newest byte is position `key`; rows before
    /// `raw_before` stay raw.
    pub fn score_at(
        &mut self,
        bytes: &[u8],
        target: u8,
        key: u64,
        raw_before: usize,
    ) -> Result<f32> {
        let prefix = self.prefix(bytes, key, raw_before)?;
        let trace = frozen_forward(&self.state, self.store, self.read, &prefix)?;
        self.push(key, &trace);
        self.observe(&prefix, &trace, target, Kind::Observed)
    }

    /// Test scoring with raw rows and no buffer push.
    #[cfg(test)]
    pub fn score(&mut self, bytes: &[u8], target: u8) -> Result<f32> {
        let prefix = self.state.shared.prefix(bytes)?;
        let trace = frozen_forward(&self.state, self.store, self.read, &prefix)?;
        self.observe(&prefix, &trace, target, Kind::Observed)
    }

    /// Test oracle: the readout `score` must take its loss from, with nothing observed.
    #[cfg(test)]
    pub fn readout(&mut self, bytes: &[u8]) -> Result<super::super::shared::Readout> {
        let prefix = self.state.shared.prefix(bytes)?;
        let trace = frozen_forward(&self.state, self.store, self.read, &prefix)?;
        self.state.shared.readout(&trace.output)
    }

    /// Test probe: each frame's history input at `bytes` after scoring `observed` pairs.
    #[cfg(test)]
    pub fn histories(&mut self, observed: &[(&[u8], u8)], bytes: &[u8]) -> Result<Vec<Vec<f32>>> {
        for (prefix, target) in observed {
            self.score(prefix, *target)?;
        }
        let prefix = self.state.shared.prefix(bytes)?;
        let frames = frozen_forward(&self.state, self.store, self.read, &prefix)?.frames;
        Ok(frames.into_iter().map(|frame| frame.history).collect())
    }

    /// Test view: the buffered state of position `key`.
    #[cfg(test)]
    pub fn buffered(&self, key: u64) -> Option<Vec<f32>> {
        Some(self.context.as_ref()?.state(key)?.to_vec())
    }

    pub(super) fn prefix(&self, bytes: &[u8], key: u64, raw_before: usize) -> Result<Prefix> {
        match &self.context {
            Some(buffer) => {
                let gate = super::super::connected_context_gate::value(&self.state.gate);
                let shared = &self.state.shared;
                Ok(connected_context::rows(shared, bytes, buffer, key, raw_before, gate)?.0)
            }
            None => self.state.shared.prefix(bytes),
        }
    }

    fn push(&mut self, key: u64, trace: &Trace) {
        if let Some(buffer) = &mut self.context {
            buffer.push(key, trace.output.clone());
        }
    }

    fn observe(&mut self, prefix: &Prefix, trace: &Trace, target: u8, kind: Kind) -> Result<f32> {
        let credit =
            connected_anchor::gather(&self.state.shared, self.store, prefix, trace, target)?;
        let shared_revision = self
            .state
            .shared_latent
            .as_ref()
            .map_or(0, |value| value.step);
        for (frame, correction) in trace.frames.iter().zip(credit.corrections) {
            self.state.memory.publish(Record {
                input: frame.input.clone(),
                output: frame.output.clone(),
                history: frame.history.clone(),
                correction,
                tile_id: frame.tile,
                revision: self.store.slots[frame.tile].meta.revision,
                shared_revision,
                epoch: self.state.epoch,
                kind,
                lane: None,
            })?;
            self.state.epoch += 1;
        }
        let options = self.state.options;
        // Scored or selected byte: its label reaches lanes only after this anchor's readout.
        if options.credit_mode.uses_lanes() {
            super::super::connected_lanes::replay(
                &mut self.state,
                self.store,
                prefix,
                target,
                options,
            )?;
        }
        Ok(credit.loss)
    }

    /// Continue `prompt` after `context` (held-out text filling the window; empty means `END`).
    pub fn generate(
        &mut self,
        context: &[u8],
        prompt: &str,
        window: usize,
        limit: usize,
        budget: &Budget<'_>,
        decode: Options,
    ) -> Result<Value> {
        decode.validate()?;
        let lead = if context.is_empty() {
            &[END][..]
        } else {
            context
        };
        let mut text = [lead, prompt.as_bytes()].concat();
        // Position t is the prefix `text[..t]`; contextual rows observe the true opening first.
        let start = text.len().saturating_sub(2).max(1);
        let first = self.observed_from(start, recent_window(&text[..start], window).len());
        let mut prompt_observations = 0;
        for t in first..text.len() {
            if budget.interrupted() {
                break;
            }
            self.score_at(recent_window(&text[..t], window), text[t], t as u64, 0)?;
            prompt_observations += usize::from(t >= start);
        }
        let mut generated = Vec::new();
        let mut stop = "byte_limit";
        let mut trace_rows = Vec::new();
        for _ in 0..limit {
            if budget.interrupted() {
                stop = "evaluation_budget_or_stop";
                break;
            }
            let key = text.len() as u64;
            let prefix = self.prefix(recent_window(&text, window), key, 0)?;
            let trace = frozen_forward(&self.state, self.store, self.read, &prefix)?;
            self.push(key, &trace);
            let readout = self.state.shared.readout(&trace.output)?;
            let next = u8::try_from(decode.decoder.choose(&readout.logits, generated.len())?)?;
            if trace_rows.len() < decode.trace_bytes {
                trace_rows.push(connected_decode::trace(
                    &self.state.shared,
                    &prefix,
                    &trace,
                    &readout,
                    next,
                    &self.state.memory,
                )?);
            }
            if next == END {
                stop = "story_end";
                break;
            }
            if decode.generated_feedback {
                self.observe(&prefix, &trace, next, Kind::SelfGenerated)?;
            }
            generated.push(next);
            text.push(next);
        }
        let mut result = json!({"prompt": prompt, "text": String::from_utf8_lossy(&generated),
            "raw_bytes": generated, "valid_utf8": std::str::from_utf8(&generated).is_ok(),
            "stop_reason": stop, "requested_bytes": limit, "generated_bytes": generated.len(),
            "generation_policy": connected_decode::POLICY, "prompt_observations": prompt_observations,
            "feedback": if decode.generated_feedback { "generated" } else { "prompt-only" },
            "diagnostic_ablation": !decode.generated_feedback,
            "self_generated_publications": self.state.memory.self_generated});
        if decode.trace_bytes > 0 {
            result["decode_trace"] = json!(trace_rows);
        }
        Ok(result)
    }
}

/// One greedy frozen route over `prefix`, reading the replay's scratch memory.
fn frozen_forward(state: &State, store: &mut Store, read: bool, prefix: &Prefix) -> Result<Trace> {
    let revisions = std::array::from_fn(|id| store.slots[id].meta.revision);
    let shared_revision = state.shared_latent.as_ref().map_or(0, |value| value.step);
    let sections = state.sections.as_ref().filter(|_| read);
    let entry = super::super::connected_sections_read::entry(sections, state.geometry, prefix)?;
    connected_anchor::forward_from(
        store,
        state.geometry,
        prefix,
        entry,
        state.options.visits,
        Draw::GREEDY,
        |tile, input| {
            let retrieved =
                state
                    .memory
                    .query(input, tile, state.epoch, &revisions, shared_revision)?;
            Ok(state.options.history_input(retrieved))
        },
    )
}
